import sympy as sp, itertools
def _sort(idx):
    idx=list(idx); s=1
    for i in range(len(idx)):
        for j in range(len(idx)-1-i):
            if idx[j]>idx[j+1]: idx[j],idx[j+1]=idx[j+1],idx[j]; s=-s
    if len(set(idx))<len(idx): return None,0
    return tuple(idx),s
def clean(w): return {k:sp.simplify(v) for k,v in w.items() if sp.simplify(v)!=0}
def add(*ws):
    r={}
    for w in ws:
        for k,v in w.items(): r[k]=r.get(k,0)+v
    return clean(r)
def scale(c,w): return clean({k:c*v for k,v in w.items()})
def wedge(a,b):
    r={}
    for I,f in a.items():
        for J,g in b.items():
            K,s=_sort(I+J)
            if K is not None: r[K]=r.get(K,0)+s*f*g
    return clean(r)
def d(w,X):
    r={}
    for I,f in w.items():
        for j,x in enumerate(X):
            K,s=_sort((j,)+I)
            if K is not None: r[K]=r.get(K,0)+s*sp.diff(f,x)
    return clean(r)
def interior(V,w):
    r={}
    for I,f in w.items():
        for p,i in enumerate(I):
            J=I[:p]+I[p+1:]
            r[J]=r.get(J,0)+(-1)**p*V[i]*f
    return clean(r)
def pullback(w,X,Y,phi):
    # phi: list of expressions in Y giving X-coordinates
    sub=dict(zip(X,phi)); r={}
    dphi=[{(j,):sp.diff(p,y) for j,y in enumerate(Y)} for p in phi]
    for I,f in w.items():
        t={():f.subs(sub,simultaneous=True)}
        for i in I: t=wedge(t,dphi[i])
        r=add(r,t)
    return r
def lie(V,w,X): return add(d(interior(V,w),X),interior(V,d(w,X)))


